// Lógica determinista: construye el registro de auditoría a partir de lo que hizo el agente.
const agente = $input.first().json;
const consulta = $('Chat Trigger').first().json.chatInput ?? '';
const maxIteraciones = $('AI Agent').params?.options?.maxIterations ?? 'n/d';
const pasos = Array.isArray(agente.intermediateSteps) ? agente.intermediateSteps : [];
const respuesta = String(agente.output ?? '');

const registros = [];
const detalle = pasos.map((paso, i) => {
  const herramienta = paso.action?.tool ?? 'desconocida';
  const entrada = paso.action?.toolInput ?? {};
  const salida = typeof paso.observation === 'string' ? paso.observation : JSON.stringify(paso.observation ?? '');
  const error = /error|failed|no se pudo/i.test(salida) && !/^\s*\[/.test(salida);
  if (herramienta === 'registrar_movimiento') {
    registros.push({ mov: entrada.mov_id, contrato: entrada.contrato_id, estado: entrada.estado, motivo: entrada.motivo });
    return `${i + 1}. registrar_movimiento → ${entrada.mov_id} | ${entrada.contrato_id} | ${entrada.estado} | ${entrada.motivo}${error ? ' | ERROR' : ''}`;
  }
  const args = Object.keys(entrada).length ? ` ${JSON.stringify(entrada)}` : '';
  return `${i + 1}. ${herramienta}${args}${error ? ' → ERROR' : ' → ok'}`;
});

const registrados = registros.filter((r) => r.estado === 'REGISTRADO');
const enRevision = registros.filter((r) => r.estado !== 'REGISTRADO');

let estado;
if (/max(imum)? iterations|stopped due to/i.test(respuesta)) estado = 'CORTE POR MÁXIMO DE ITERACIONES';
else if (enRevision.length) estado = `REQUIERE REVISIÓN HUMANA (${enRevision.length})`;
else if (registrados.length) estado = `PAGOS REGISTRADOS (${registrados.length})`;
else if (pasos.length) estado = 'CONSULTA RESUELTA SIN CAMBIOS';
else estado = 'RESPONDIDA SIN HERRAMIENTAS';

const logSlack = [
  `*Tarea completada* · Agente de Conciliación de Cobros`,
  `*Estado:* ${estado}`,
  `*Ejecución:* ${$execution.id} · ${$now.toFormat('yyyy-MM-dd HH:mm')}`,
  `*Petición:* ${consulta}`,
  `*Herramientas usadas:* ${pasos.length} (máximo de iteraciones: ${maxIteraciones})`,
  ...(detalle.length ? detalle : ['Ninguna: el agente decidió no usar herramientas.']),
  `*Respuesta del agente:*`,
  respuesta.slice(0, 1800),
].join('\n');

return [{ json: { estado, registrados: registrados.length, en_revision: enRevision.length, logSlack } }];
